=================== Tools/Jam/Start-EditorMcp.ps1
<#
Start-EditorMcp.ps1 - Abre el Editor UE 5.9 con el servidor MCP y espera a que este listo.
Uso:  powershell -File Tools/Jam/Start-EditorMcp.ps1 -Project D:\Jam\MiJuego\MiJuego.uproject -Port 8059
#>
param(
    [Parameter(Mandatory = $true)][string]$Project,
    [int]$Port = 8059,
    [string]$EngineDir = 'C:\Program Files\Epic Games\UE_5.9',
    [int]$TimeoutSeconds = 900
)
$exe = Join-Path $EngineDir 'Engine\Binaries\Win64\UnrealEditor.exe'
if (-not (Test-Path $exe)) { throw "No existe $exe" }
$name = [IO.Path]::GetFileNameWithoutExtension($Project)
$log = Join-Path (Split-Path $Project -Parent) "Saved\Logs\$name.log"
$start = Get-Date
$p = Start-Process -FilePath $exe -ArgumentList "`"$Project`"", '-ModelContextProtocolStartServer', "-ModelContextProtocolPort=$Port" -PassThru
$t = 0
while ($t -lt $TimeoutSeconds) {
    Start-Sleep 5; $t += 5
    if ($p.HasExited) { Write-Host "El Editor se cerro (exit $($p.ExitCode))"; exit 1 }
    if ((Test-Path $log) -and (Get-Item $log).LastWriteTime -gt $start) {
        $m = Select-String $log -Pattern 'Starting MCP server|MCP server listener could not start' | Select-Object -Last 1
        if ($m) { Write-Host $m.Line; if ($m.Line -match 'could not') { exit 1 }; Write-Host "MCP listo en $t s (PID $($p.Id))"; exit 0 }
    }
}
Write-Host "Timeout esperando MCP ($TimeoutSeconds s). La primera apertura compila shaders: reintentar con mas tiempo."
exit 1
=================== Tools/Jam/Test-UnrealMcp.ps1
<#
Test-UnrealMcp.ps1 - Prueba de aceptacion del servidor MCP del Editor (UE 5.9).
Hace: initialize -> notifications/initialized -> tools/list -> list_toolsets ->
call_tool EditorToolset.LevelToolset.GetCurrentLevel. Imprime PASS/FAIL por paso.

Uso:  powershell -File Tools/Jam/Test-UnrealMcp.ps1 -Port 8059
#>
param([int]$Port = 8059)
$u = "http://127.0.0.1:$Port/mcp"
$fail = 0

function Invoke-Mcp($body, $sid) {
    $h = @{ 'Accept' = 'application/json, text/event-stream' }
    if ($sid) { $h['Mcp-Session-Id'] = $sid }
    $r = Invoke-WebRequest -Uri $u -Method Post -Headers $h -ContentType 'application/json' -Body ($body | ConvertTo-Json -Depth 8 -Compress) -UseBasicParsing -TimeoutSec 30
    $txt = if ($r.Content -is [byte[]]) { [Text.Encoding]::UTF8.GetString($r.Content) } else { [string]$r.Content }
    if ($txt -match '^\s*(event:|data:)') { $txt = (($txt -split "`n") | Where-Object { $_ -like 'data:*' } | ForEach-Object { $_.Substring(5) }) -join '' }
    $json = $null
    if ($txt.Trim()) { $json = $txt | ConvertFrom-Json }
    return @{ Json = $json; Sid = $r.Headers['Mcp-Session-Id'] }
}
# Recien abierto, el Editor corre una "slow task" (shaders, carga) que bloquea las tools y
# responde "Not run: ... slow task". Se reintenta hasta 5 minutos.
function Invoke-McpTool($body, $sid) {
    $limit = (Get-Date).AddMinutes(5)
    while ($true) {
        $r = Invoke-Mcp $body $sid
        $t = [string]$r.Json.result.content[0].text
        if ($t -notmatch 'slow task' -or (Get-Date) -gt $limit) { return $r }
        Start-Sleep 5
    }
}
function Step($name, [scriptblock]$b) {
    try { $msg = & $b; Write-Host "PASS  $name  $msg" } catch { $script:fail++; Write-Host "FAIL  $name  $($_.Exception.Message)" }
}

$sid = $null
Step 'initialize' {
    $r = Invoke-Mcp @{ jsonrpc = '2.0'; id = 1; method = 'initialize'; params = @{ protocolVersion = '2025-06-18'; capabilities = @{}; clientInfo = @{ name = 'jam-probe'; version = '1' } } } $null
    $script:sid = $r.Sid
    $v = $r.Json.result.serverInfo.version
    if (-not $v) { throw 'sin serverInfo' }
    "server=$($r.Json.result.serverInfo.name) version=$v project=$($r.Json.result._meta.'com.epicgames.unrealengine/instance'.projectName)"
}
Step 'initialized' { [void](Invoke-Mcp @{ jsonrpc = '2.0'; method = 'notifications/initialized' } $sid); 'ok' }
Step 'tools/list' {
    $r = Invoke-Mcp @{ jsonrpc = '2.0'; id = 2; method = 'tools/list' } $sid
    $n = @($r.Json.result.tools).Count; if ($n -lt 1) { throw 'cero tools' }; "tools=$n ($((@($r.Json.result.tools) | ForEach-Object name) -join ', '))"
}
Step 'list_toolsets' {
    $r = Invoke-McpTool @{ jsonrpc = '2.0'; id = 3; method = 'tools/call'; params = @{ name = 'list_toolsets'; arguments = @{} } } $sid
    $t = $r.Json.result.content[0].text
    $n = @(($t -split "`n") | Where-Object { $_ -match '^- ' }).Count
    if ($n -lt 10) { throw "solo $n toolsets" }; "toolsets~$n"
}
Step 'call_tool GetCurrentLevel' {
    $r = Invoke-McpTool @{ jsonrpc = '2.0'; id = 4; method = 'tools/call'; params = @{ name = 'call_tool'; arguments = @{ toolset_name = 'EditorToolset.LevelToolset'; tool_name = 'GetCurrentLevel'; arguments = @{} } } } $sid
    if ($r.Json.result.isError) { throw $r.Json.result.content[0].text }
    "level=$($r.Json.result.structuredContent.returnValue)"
}
if ($fail -eq 0) { Write-Host 'RESULTADO: PASS'; exit 0 } else { Write-Host "RESULTADO: FAIL ($fail pasos)"; exit 1 }
=================== Tools/Jam/Stop-EditorMcp.ps1
<#
Stop-EditorMcp.ps1 - Cierra el Editor de forma ordenada por MCP (consola: QUIT_EDITOR).
Cerrar la ventana a mano/CloseMainWindow no basta en 5.9 (queda colgado). Nunca matar el proceso.
ANTES: guardar el trabajo. QUIT_EDITOR puede mostrar el dialogo de guardar si hay cambios.
Uso:  powershell -File Tools/Jam/Stop-EditorMcp.ps1 -Port 8059
#>
param([int]$Port = 8059, [int]$TimeoutSeconds = 120)
$u = "http://127.0.0.1:$Port/mcp"
$h = @{ 'Accept' = 'application/json, text/event-stream' }
$init = @{ jsonrpc = '2.0'; id = 1; method = 'initialize'; params = @{ protocolVersion = '2025-06-18'; capabilities = @{}; clientInfo = @{ name = 'jam-stop'; version = '1' } } } | ConvertTo-Json -Depth 6 -Compress
$r = Invoke-WebRequest -Uri $u -Method Post -Headers $h -ContentType 'application/json' -Body $init -UseBasicParsing -TimeoutSec 20
$initTxt = if ($r.Content -is [byte[]]) { [Text.Encoding]::UTF8.GetString($r.Content) } else { [string]$r.Content }
$meta = ($initTxt | ConvertFrom-Json).result._meta.'com.epicgames.unrealengine/instance'
$pid0 = $meta.processId
$projDir = $meta.projectDirectory
$h['Mcp-Session-Id'] = $r.Headers['Mcp-Session-Id']
# Cerrar primero los editores de assets abiertos: con el editor de animacion (Persona) abierto,
# QUIT_EDITOR crasheo al apagar (EXCEPTION_ACCESS_VIOLATION en UnrealEditor-Persona, 2026-11-10).
function Invoke-EdTool($tool, $toolArgs) {
    $b = @{ jsonrpc = '2.0'; id = 3; method = 'tools/call'; params = @{ name = 'call_tool'; arguments = @{ toolset_name = 'EditorToolset.EditorAppToolset'; tool_name = $tool; arguments = $toolArgs } } } | ConvertTo-Json -Depth 8 -Compress
    $x = Invoke-WebRequest -Uri $u -Method Post -Headers $h -ContentType 'application/json' -Body $b -UseBasicParsing -TimeoutSec 30
    $s = if ($x.Content -is [byte[]]) { [Text.Encoding]::UTF8.GetString($x.Content) } else { [string]$x.Content }
    if ($s -match '^\s*(event:|data:)') { $s = (($s -split "`n") | Where-Object { $_ -like 'data:*' } | ForEach-Object { $_.Substring(5) }) -join '' }
    return ($s | ConvertFrom-Json)
}
try {
    $open = @((Invoke-EdTool 'GetOpenAssets' @{}).result.structuredContent.returnValue)
    foreach ($a in $open) {
        $p = if ($a -is [string]) { $a } elseif ($a.refPath) { $a.refPath } elseif ($a.objectPath) { $a.objectPath } else { [string]$a }
        if ($p) {
            # unsavedChanges es obligatorio (Fail/Save/Discard); sin el, la tool falla y el editor sigue abierto.
            $c = Invoke-EdTool 'CloseEditorForAsset' @{ assetPath = $p; unsavedChanges = 'Save' }
            if ($c.result.isError) { Write-Host "AVISO: no se pudo cerrar el editor de $p : $($c.result.content[0].text)" } else { Write-Host "Cerrado editor de asset: $p" }
        }
    }
    # CloseEditorForAsset vuelve antes de que la ventana se destruya; si QUIT_EDITOR llega en ese
    # momento, Persona crashea igual (2026-11-10, segunda prueba). Esperar a que no quede ninguno.
    if ($open.Count -gt 0) {
        $limit2 = (Get-Date).AddSeconds(20)
        while ((Get-Date) -lt $limit2 -and @((Invoke-EdTool 'GetOpenAssets' @{}).result.structuredContent.returnValue).Count -gt 0) { Start-Sleep 1 }
        Start-Sleep 3
    }
} catch { Write-Host "Aviso: no se pudieron cerrar los editores de assets ($($_.Exception.Message))" }
$quit = @{ jsonrpc = '2.0'; id = 2; method = 'tools/call'; params = @{ name = 'call_tool'; arguments = @{ toolset_name = 'ConsoleToolset.ConsoleToolset'; tool_name = 'RunConsoleCommand'; arguments = @{ Command = 'QUIT_EDITOR' } } } } | ConvertTo-Json -Depth 8 -Compress
# Si el Editor esta en una "slow task" (shaders/carga) la orden no se ejecuta: reintentar hasta 5 min.
$limit = (Get-Date).AddMinutes(5)
while ($true) {
    $txt = ''
    try {
        $q = Invoke-WebRequest -Uri $u -Method Post -Headers $h -ContentType 'application/json' -Body $quit -UseBasicParsing -TimeoutSec 20
        $txt = if ($q.Content -is [byte[]]) { [Text.Encoding]::UTF8.GetString($q.Content) } else { [string]$q.Content }
    } catch { break }   # sin respuesta = el Editor ya se esta cerrando
    if ($txt -notmatch 'slow task' -or (Get-Date) -gt $limit) { break }
    Start-Sleep 5
}
$t = 0
while ($t -lt $TimeoutSeconds) {
    Start-Sleep 3; $t += 3
    if (-not (Get-Process -Id $pid0 -ErrorAction SilentlyContinue)) {
        Write-Host "Editor (PID $pid0) cerrado en $t s"
        $log = if ($projDir) { Get-ChildItem (Join-Path $projDir 'Saved\Logs') -Filter *.log -ErrorAction SilentlyContinue | Sort-Object LastWriteTime | Select-Object -Last 1 }
        if ($log -and (Select-String $log.FullName -Pattern 'Unhandled Exception|Fatal error!' -Quiet)) { Write-Host "AVISO: el Editor crasheo al cerrar; ver $($log.FullName) y Saved\Crashes" }
        # Bitacora: rescatar las acciones de agentes del log ANTES de que el proximo arranque lo rote.
        $collector = Join-Path (Split-Path $PSScriptRoot -Parent) 'Devlog\Collect-UnrealAgentLog.ps1'
        if ($projDir -and (Test-Path $collector)) { & $collector -ProjectDir $projDir }
        exit 0
    }
}
Write-Host "El Editor (PID $pid0) sigue abierto: probablemente hay un dialogo de guardar. Revisarlo a mano; NO matar el proceso."
exit 1
=================== Tools/Jam/Package-Jam.ps1
<#
Package-Jam.ps1 - Empaqueta el juego para la entrega de la jam y arma el zip.
Receta probada en UE 5.9.0 (CL 60351404) el 2026-11-09:
  - UAT BuildCookRun Win64 Development con -build -cook -stage -pak -iostore -archive.
  - NO usar -nocompileeditor: con plugins no-default activos (p. ej. AllToolsets) el cook
    busca <Proyecto>Editor.target y falla si no se compilo.
  - Config/DefaultGame.ini con bUseZenStore=False (en la maquina de assets el cook murio
    escribiendo en la carpeta de Zen; causa no confirmada). El script lo comprueba.
  - El zip EXCLUYE los .pdb (simbolos de depuracion, ~340 MB que no hacen falta).
  - Limite de la jam: zip < 1 GB, nombre TeamName_GameName.zip.

Uso:
  powershell -File Tools/Jam/Package-Jam.ps1 -Project D:\Jam\MiJuego\MiJuego.uproject -ZipName Equipo_Juego
#>
param(
    [Parameter(Mandatory = $true)][string]$Project,
    [Parameter(Mandatory = $true)][string]$ZipName,
    [string]$EngineDir = 'C:\Program Files\Epic Games\UE_5.9',
    [string]$Config = 'Development'
)
$ErrorActionPreference = 'Stop'
$projDir = Split-Path $Project -Parent
$buildDir = Join-Path $projDir 'Build'
$logFile = Join-Path $projDir 'Saved\uat_package.log'
[void][IO.Directory]::CreateDirectory((Split-Path $logFile -Parent))

$game = Join-Path $projDir 'Config\DefaultGame.ini'
$zenOff = (Test-Path $game) -and (Select-String $game -Pattern '^\s*bUseZenStore\s*=\s*False' -Quiet)
if (-not $zenOff) {
    Write-Host 'AVISO: falta bUseZenStore=False en Config/DefaultGame.ini. Se agrega.'
    Add-Content $game "`r`n[/Script/UnrealEd.ProjectPackagingSettings]`r`nbUseZenStore=False`r`n"
}

$uat = Join-Path $EngineDir 'Engine\Build\BatchFiles\RunUAT.bat'
$uatArgs = @('BuildCookRun', "-project=`"$Project`"", '-platform=Win64', "-clientconfig=$Config",
          '-build', '-cook', '-stage', '-pak', '-iostore', '-archive', "-archivedirectory=`"$buildDir`"",
          '-noP4', '-utf8output', '-unattended')
Write-Host "UAT -> $logFile"
& cmd.exe /d /c "`"$uat`" $($uatArgs -join ' ') > `"$logFile`" 2>&1"
$code = $LASTEXITCODE
Get-Content $logFile -Tail 4
if ($code -ne 0) {
    Write-Host "FALLO UAT (exit $code). Primeras lineas de error:"
    Select-String $logFile -Pattern 'Error:|Exception|Cook failed' | Select-Object -First 15 | ForEach-Object Line
    exit $code
}

$win = Join-Path $buildDir 'Windows'
$zip = Join-Path $projDir "$ZipName.zip"
if (Test-Path $zip) { Remove-Item $zip -Force }
Remove-Item (Join-Path $win '*\Saved') -Recurse -Force -ErrorAction SilentlyContinue
Add-Type -AssemblyName System.IO.Compression.FileSystem
$z = [System.IO.Compression.ZipFile]::Open($zip, 'Create')
try {
    Get-ChildItem $win -Recurse -File | Where-Object { $_.Extension -ne '.pdb' } | ForEach-Object {
        [void][System.IO.Compression.ZipFileExtensions]::CreateEntryFromFile($z, $_.FullName, $_.FullName.Substring($win.Length + 1), 'Optimal')
    }
} finally { $z.Dispose() }
$mb = [math]::Round((Get-Item $zip).Length / 1MB, 1)
Write-Host "ZIP: $zip ($mb MB)"
if ($mb -ge 1024) { Write-Host 'FALLO: el zip supera 1 GB (limite de la jam). Usar butler o recortar contenido.'; exit 2 }
exit 0

