=================== .claude/hooks/devlog-hook.ps1
﻿# devlog-hook.ps1 - Hook de Claude Code para la bitacora de la jam.
#
# Que hace: cada evento de Claude Code (inicio de sesion, prompt del usuario, cada
# herramienta usada, fin de subagente, fin de turno, fin de sesion) se agrega como UNA
# linea JSON a:
#     Devlog/raw/<MAQUINA>/<AAAA-MM-DD>/claude-<session_id>.jsonl
# En Stop y SessionEnd copia ademas el transcript completo de la sesion a
#     Devlog/raw/<MAQUINA>/<AAAA-MM-DD>/transcripts/<session_id>.jsonl
#
# Instalacion: a NIVEL DE USUARIO (%USERPROFILE%\.claude\settings.json, ver
# Tools/Devlog/Install-DevlogHooks.ps1), no a nivel de proyecto: los hooks de proyecto solo
# se cargan si Claude Code arranca justo en la raiz, y una sesion abierta en una subcarpeta
# no dejaria rastro (probado 2026-11-09).
#
# Reglas de diseno:
#  - FAIL-OPEN: pase lo que pase sale con exit 0 y sin stdout. Un fallo de la bitacora
#    nunca debe bloquear al agente.
#  - No depende del esquema exacto de cada evento: guarda el payload completo, solo
#    recorta los campos largos (tool_response, tool_input, prompt) a MaxChars.
#  - UTF-8 de punta a punta (PowerShell 5.1 rompe la n con tilde si se lee stdin con la
#    codificacion por defecto).
#  - Maquina: variable de entorno JAM_MACHINE si existe; si no, COMPUTERNAME.
#  - Fechas en UTC (dos maquinas, un solo eje de tiempo).

$MaxChars = 4000

try {
    $reader = New-Object System.IO.StreamReader([Console]::OpenStandardInput(), (New-Object System.Text.UTF8Encoding($false)))
    $raw = $reader.ReadToEnd()
    if (-not $raw) { exit 0 }
    $p = $raw | ConvertFrom-Json

    # Raiz de la jam: se busca HACIA ARRIBA desde la carpeta de la sesion un "Devlog\.jamroot".
    # Asi funciona aunque Claude Code se abra en una subcarpeta (p. ej. la del .uproject), y
    # este hook, instalado a nivel de usuario, no hace NADA en sesiones fuera de la jam.
    $root = $null
    foreach ($start in @([string]$p.cwd, [string]$env:CLAUDE_PROJECT_DIR, (Get-Location).Path)) {
        if (-not $start) { continue }
        $d = $start
        while ($d) {
            if (Test-Path -LiteralPath (Join-Path $d 'Devlog\.jamroot')) { $root = $d; break }
            $parent = Split-Path $d -Parent
            if ($parent -eq $d) { break }
            $d = $parent
        }
        if ($root) { break }
    }
    if (-not $root) { exit 0 }

    $machine = $env:JAM_MACHINE
    if (-not $machine) { $machine = [Environment]::GetEnvironmentVariable('JAM_MACHINE','User') }
if (-not $machine) { $machine = $env:COMPUTERNAME }
    $nowUtc = [DateTime]::UtcNow
    $day = $nowUtc.ToString('yyyy-MM-dd')
    $sid = [string]$p.session_id
    if (-not $sid) { $sid = 'nosession' }

    $dir = Join-Path $root "Devlog\raw\$machine\$day"
    [void][IO.Directory]::CreateDirectory($dir)

    # Recorta campos largos sin perder el resto del payload.
    foreach ($field in 'tool_response', 'tool_input', 'prompt', 'last_assistant_message') {
        if ($p.PSObject.Properties.Name -contains $field) {
            $v = $p.$field
            $s = if ($v -is [string]) { $v } else { $v | ConvertTo-Json -Depth 8 -Compress }
            if ($s.Length -gt $MaxChars) {
                $p.$field = $s.Substring(0, $MaxChars) + " ...[recortado: $($s.Length) chars]"
            }
        }
    }

    $entry = [ordered]@{
        ts_utc  = $nowUtc.ToString('o')
        machine = $machine
        agent   = 'claude-code'
        event   = [string]$p.hook_event_name
        session = $sid
        payload = $p
    }
    $line = ($entry | ConvertTo-Json -Depth 10 -Compress)
    $bytes = (New-Object System.Text.UTF8Encoding($false)).GetBytes($line + "`n")
    # Claude Code lanza herramientas en paralelo -> varios hooks escriben a la vez en el
    # mismo archivo. Se abre con FileShare.ReadWrite y se reintenta si choca (si no, el
    # evento se perderia en silencio).
    $target = Join-Path $dir "claude-$sid.jsonl"
    $written = $false
    for ($i = 0; $i -lt 40 -and -not $written; $i++) {
        try {
            $fs = New-Object System.IO.FileStream($target, [IO.FileMode]::Append, [IO.FileAccess]::Write, [IO.FileShare]::ReadWrite)
            try { $fs.Write($bytes, 0, $bytes.Length) } finally { $fs.Dispose() }
            $written = $true
        } catch { Start-Sleep -Milliseconds (25 + (Get-Random -Maximum 75)) }
    }
    if (-not $written) { throw "No se pudo escribir $target tras 40 intentos" }

    # Transcript completo: la fuente mas rica para la bitacora.
    if (($p.hook_event_name -eq 'Stop' -or $p.hook_event_name -eq 'SessionEnd' -or $p.hook_event_name -eq 'SubagentStop') -and $p.transcript_path) {
        $t = [string]$p.transcript_path
        if (Test-Path -LiteralPath $t) {
            $tdir = Join-Path $dir 'transcripts'
            [void][IO.Directory]::CreateDirectory($tdir)
            Copy-Item -LiteralPath $t -Destination (Join-Path $tdir "$sid.jsonl") -Force
        }
    }
} catch {
    try {
        $fallback = Join-Path ([IO.Path]::GetTempPath()) 'jam-devlog-hook-errors.log'
        Add-Content -Path $fallback -Value ("{0} {1}" -f [DateTime]::UtcNow.ToString('o'), $_.Exception.Message)
    } catch {}
}
exit 0
=================== Tools/Devlog/Install-DevlogHooks.ps1
<#
Install-DevlogHooks.ps1 - Instala los hooks de bitacora en la configuracion de USUARIO de
Claude Code (%USERPROFILE%\.claude\settings.json), apuntando con ruta absoluta al hook de
esta jam.

Por que a nivel de usuario: los hooks de proyecto (.claude/settings.json) solo se cargan si
Claude Code arranca justo en la raiz; una sesion abierta en una subcarpeta (p. ej. la del
.uproject) no registraria nada. El hook busca hacia arriba "Devlog\.jamroot", asi que fuera
de la jam no hace nada.

- Hace copia de seguridad de settings.json antes de tocarlo (settings.json.bak-<fecha>).
- Fusiona: conserva todos los demas ajustes y hooks; solo quita/pone las entradas que apuntan
  a devlog-hook.ps1 (idempotente, se puede correr varias veces).
- -Uninstall quita esas entradas.

Uso (desde la raiz de la jam):
  powershell -NoProfile -ExecutionPolicy Bypass -File Tools/Devlog/Install-DevlogHooks.ps1
#>
param(
    [string]$JamRoot = (Split-Path (Split-Path $PSScriptRoot -Parent) -Parent),
    [string]$SettingsPath = (Join-Path $env:USERPROFILE '.claude\settings.json'),
    [switch]$Uninstall
)
$ErrorActionPreference = 'Stop'
$hook = Join-Path $JamRoot '.claude\hooks\devlog-hook.ps1'
if (-not $Uninstall -and -not (Test-Path $hook)) { throw "No existe $hook" }
if (-not $Uninstall -and -not (Test-Path (Join-Path $JamRoot 'Devlog\.jamroot'))) { throw "Falta $JamRoot\Devlog\.jamroot (marca de la raiz de la jam)" }

$utf8 = New-Object System.Text.UTF8Encoding($false)
[void][IO.Directory]::CreateDirectory((Split-Path $SettingsPath -Parent))
$json = '{}'
if (Test-Path $SettingsPath) {
    Copy-Item $SettingsPath ("$SettingsPath.bak-" + (Get-Date -Format 'yyyyMMdd-HHmmss'))
    $json = [IO.File]::ReadAllText($SettingsPath, $utf8)
    if (-not $json.Trim()) { $json = '{}' }
}
$s = $json | ConvertFrom-Json
if (-not ($s.PSObject.Properties.Name -contains 'hooks')) { $s | Add-Member -NotePropertyName hooks -NotePropertyValue ([pscustomobject]@{}) }

$cmd = 'powershell.exe -NoProfile -ExecutionPolicy Bypass -File "' + ($hook -replace '\\', '/') + '"'
$events = [ordered]@{ SessionStart = 15; UserPromptSubmit = 15; PostToolUse = 15; SubagentStop = 15; Stop = 30; SessionEnd = 30 }

foreach ($ev in $events.Keys) {
    $existing = @()
    if ($s.hooks.PSObject.Properties.Name -contains $ev) { $existing = @($s.hooks.$ev) }
    # quitar entradas previas de este hook
    $kept = @()
    foreach ($group in $existing) {
        $inner = @($group.hooks | Where-Object { [string]$_.command -notmatch 'devlog-hook\.ps1' })
        if ($inner.Count -gt 0) { $group.hooks = $inner; $kept += $group }
    }
    if (-not $Uninstall) {
        $entry = [ordered]@{ hooks = @([ordered]@{ type = 'command'; command = $cmd; timeout = $events[$ev] }) }
        if ($ev -eq 'PostToolUse') { $entry = [ordered]@{ matcher = '*'; hooks = $entry.hooks } }
        $kept += [pscustomobject]$entry
    }
    if ($s.hooks.PSObject.Properties.Name -contains $ev) { $s.hooks.PSObject.Properties.Remove($ev) }
    if ($kept.Count -gt 0) { $s.hooks | Add-Member -NotePropertyName $ev -NotePropertyValue @($kept) }
}
[IO.File]::WriteAllText($SettingsPath, ($s | ConvertTo-Json -Depth 20), $utf8)
if ($Uninstall) { Write-Host "Hooks de bitacora quitados de $SettingsPath" } else { Write-Host "Hooks de bitacora instalados en $SettingsPath -> $hook" }
=================== Tools/Devlog/Invoke-LoggedAgent.ps1
﻿<#
Invoke-LoggedAgent.ps1 - Ejecuta CUALQUIER agente externo (Codex, cursor-agent, OpenCode,
DeepSeek dsh, Gemini, scripts de generacion de assets...) dejando registro en la bitacora.

Los hooks de .claude solo ven a Claude Code. Todo lo demas DEBE lanzarse por este wrapper,
o no existira en la bitacora.

Uso (desde la raiz del proyecto de la jam):
  powershell -File Tools/Devlog/Invoke-LoggedAgent.ps1 -Agent codex -Model gpt-6.1-sol `
      -PromptFile Prompts/review_x.md -Purpose "revision del sistema X" `
      -Shell cmd -Command 'codex exec -m gpt-6.1-sol -s read-only -C . - < Prompts/review_x.md'
  powershell -File Tools/Devlog/Invoke-LoggedAgent.ps1 -Agent cursor-agent -Model composer-2.5-fast `
      -PromptFile Prompts/tarea.md -Purpose "implementar X" `
      -Command "& 'C:\Users\<user>\AppData\Local\cursor-agent\cursor-agent.ps1' -p --trust --workspace . (Get-Content Prompts/tarea.md -Raw)"

Que guarda en Devlog/raw/<MAQUINA>/<AAAA-MM-DD>/:
  agents.jsonl                 una linea "start" y una "end" por ejecucion
  agents/<runId>/prompt.md     copia del prompt
  agents/<runId>/output.txt    stdout+stderr completos del agente
  agents/<runId>/diffstat.txt  git diff --stat al terminar (que archivos toco)
#>
param(
    [Parameter(Mandatory = $true)][string]$Agent,
    [Parameter(Mandatory = $true)][string]$Command,
    [string]$Model = '',
    [string]$PromptFile = '',
    [string]$Purpose = '',
    # powershell (por defecto): sirve para CLIs .ps1 como cursor-agent y para "& 'ruta' args".
    # cmd: cuando el comando usa redireccion de entrada "< prompt.md" (codex exec - < archivo).
    [ValidateSet('powershell', 'cmd')][string]$Shell = 'powershell'
)

$ErrorActionPreference = 'Continue'
$utf8 = New-Object System.Text.UTF8Encoding($false)
$root = (Get-Location).Path
$machine = if ($env:JAM_MACHINE) { $env:JAM_MACHINE } elseif ([Environment]::GetEnvironmentVariable('JAM_MACHINE','User')) { [Environment]::GetEnvironmentVariable('JAM_MACHINE','User') } else { $env:COMPUTERNAME }
$start = [DateTime]::UtcNow
$day = $start.ToString('yyyy-MM-dd')
$runId = '{0}-{1}-{2}' -f $start.ToString('HHmmss'), $Agent, ([guid]::NewGuid().ToString('N').Substring(0, 6))
$dayDir = Join-Path $root "Devlog\raw\$machine\$day"
$runDir = Join-Path $dayDir "agents\$runId"
[void][IO.Directory]::CreateDirectory($runDir)
$jsonl = Join-Path $dayDir 'agents.jsonl'

function Add-Line($obj) {
    [IO.File]::AppendAllText($jsonl, (($obj | ConvertTo-Json -Depth 6 -Compress) + "`n"), $utf8)
}

$head = ''
try { $head = (git rev-parse --short HEAD 2>$null) } catch {}
if ($PromptFile -and (Test-Path -LiteralPath $PromptFile)) {
    Copy-Item -LiteralPath $PromptFile -Destination (Join-Path $runDir 'prompt.md') -Force
}

Add-Line ([ordered]@{
    ts_utc = $start.ToString('o'); machine = $machine; agent = $Agent; event = 'start'
    run = $runId; model = $Model; purpose = $Purpose; prompt_file = $PromptFile
    command = $Command; git_head = $head
})

$outFile = Join-Path $runDir 'output.txt'
# La salida de los CLIs nativos se decodifica como UTF-8 (si no, PS 5.1 usa la pagina OEM
# y la n con tilde sale rota) y se guarda en UTF-8 (Tee-Object de PS 5.1 escribe UTF-16).
$prevOut = [Console]::OutputEncoding
[Console]::OutputEncoding = $utf8
$sw = New-Object System.IO.StreamWriter($outFile, $false, $utf8)
try {
    if ($Shell -eq 'cmd') {
        & cmd.exe /d /c "$Command 2>&1" | ForEach-Object { $s = [string]$_; $sw.WriteLine($s); Write-Host $s }
    } else {
        & powershell.exe -NoProfile -ExecutionPolicy Bypass -Command "[Console]::OutputEncoding=[Text.Encoding]::UTF8; `$OutputEncoding=[Text.Encoding]::UTF8; $Command; exit `$LASTEXITCODE" 2>&1 |
            ForEach-Object { $s = [string]$_; $sw.WriteLine($s); Write-Host $s }
    }
    $code = $LASTEXITCODE
} finally { $sw.Dispose(); [Console]::OutputEncoding = $prevOut }
$end = [DateTime]::UtcNow

$diffstat = ''
try { $diffstat = (git diff --stat 2>$null | Out-String); [IO.File]::WriteAllText((Join-Path $runDir 'diffstat.txt'), $diffstat, $utf8) } catch {}
$tail = ''
if (Test-Path $outFile) { $tail = ((Get-Content $outFile -Tail 15 -Encoding UTF8 -ErrorAction SilentlyContinue) -join "`n") }

Add-Line ([ordered]@{
    ts_utc = $end.ToString('o'); machine = $machine; agent = $Agent; event = 'end'
    run = $runId; exit_code = $code; seconds = [int]($end - $start).TotalSeconds
    output_tail = $tail; diffstat = $diffstat
})
exit $code
=================== Tools/Devlog/Collect-UnrealAgentLog.ps1
﻿<#
Collect-UnrealAgentLog.ps1 - Rescata del log del Editor todo lo que hicieron los agentes
DENTRO de Unreal: llamadas MCP (Claude u otro cliente), Unreal Assistant y Unreal Canvas.

Por que hace falta: esas acciones no pasan por los hooks de Claude Code. El Editor las
escribe en <Proyecto>/Saved/Logs/*.log (lineas LogModelContextProtocol: Running tool...).
El Editor rota el log en cada arranque (los viejos quedan como *-backup-*.log), asi que
corre esto AL FINAL DE CADA DIA y SIEMPRE antes de borrar Saved/.

Stop-EditorMcp.ps1 lo llama solo al cerrar el Editor (antes de que el log se rote).

Uso:  powershell -File Tools/Devlog/Collect-UnrealAgentLog.ps1 -ProjectDir <carpeta del .uproject>
Salida: <raiz del repo>/Devlog/raw/<MAQUINA>/unreal/<proyecto>__<log>.jsonl
        (la raiz del repo es la carpeta dos niveles arriba de este script, aunque el
        .uproject viva en una subcarpeta; idempotente: reescribe por log)
Categorias verificadas en el codigo de UE 5.9: LogModelContextProtocol, LogAIAssistant
(Unreal Assistant), LogUnrealCanvas* (Canvas). Que el contenido de cada linea sea util
para la bitacora (p. ej. si Canvas escribe el prompt) NO esta verificado.
#>
param(
    [string]$ProjectDir = '.',
    [string]$OutRoot = (Split-Path (Split-Path $PSScriptRoot -Parent) -Parent),
    [string]$Pattern = 'LogModelContextProtocol|LogAIAssistant|LogUnrealCanvas|LogToolsetRegistry'
)
$utf8 = New-Object System.Text.UTF8Encoding($false)
$machine = if ($env:JAM_MACHINE) { $env:JAM_MACHINE } elseif ([Environment]::GetEnvironmentVariable('JAM_MACHINE','User')) { [Environment]::GetEnvironmentVariable('JAM_MACHINE','User') } else { $env:COMPUTERNAME }
$logs = Join-Path $ProjectDir 'Saved\Logs'
if (-not (Test-Path $logs)) { Write-Host "No existe $logs"; exit 0 }
$proj = Split-Path (Resolve-Path $ProjectDir).Path -Leaf
$outDir = Join-Path $OutRoot "Devlog\raw\$machine\unreal"
[void][IO.Directory]::CreateDirectory($outDir)
$total = 0
foreach ($f in Get-ChildItem $logs -Filter *.log) {
    $lines = Select-String -Path $f.FullName -Pattern $Pattern -Encoding UTF8 -ErrorAction SilentlyContinue
    if (-not $lines) { continue }
    $sb = New-Object System.Text.StringBuilder
    foreach ($l in $lines) {
        $ts = ''
        if ($l.Line -match '^\[(\d{4}\.\d{2}\.\d{2}-\d{2}\.\d{2}\.\d{2}:\d{3})\]') { $ts = $Matches[1] }
        $tool = ''
        if ($l.Line -match "tool: '([^']+)'") { $tool = $Matches[1] }
        $obj = [ordered]@{ log_ts = $ts; machine = $machine; agent = 'unreal-editor'; source_log = $f.Name; tool = $tool; line = $l.Line.Trim() }
        [void]$sb.Append(($obj | ConvertTo-Json -Compress)).Append("`n")
        $total++
    }
    [IO.File]::WriteAllText((Join-Path $outDir ($proj + '__' + $f.BaseName + '.jsonl')), $sb.ToString(), $utf8)
}
Write-Host "Lineas de agentes en Unreal recolectadas: $total -> $outDir"
=================== Tools/Devlog/New-DevlogDay.ps1
﻿<#
New-DevlogDay.ps1 - Arma el BORRADOR de la entrada diaria de la bitacora a partir de los
registros crudos de TODAS las maquinas (Devlog/raw/*/<fecha>/) y de git.

El borrador sale ya REDACTADO (claves, tokens, correos) porque es lo que se publica.
Los crudos (Devlog/raw) nunca se publican tal cual.

Uso:  powershell -File Tools/Devlog/New-DevlogDay.ps1 -Date 2026-11-12
Salida: Devlog/days/<fecha>_DRAFT.md   (la persona lo completa usando TEMPLATE_DAY.md). Sale en ingles: la bitacora publica va en ingles (Official Rules 7(i)).
#>
param([string]$Date = ([DateTime]::UtcNow.ToString('yyyy-MM-dd')))

$utf8 = New-Object System.Text.UTF8Encoding($false)
$root = (Get-Location).Path

function Redact([string]$s) {
    if (-not $s) { return $s }
    $s = $s -replace 'sk-[A-Za-z0-9_\-]{16,}', '[KEY-REDACTED]'
    $s = $s -replace '(gh[pousr]_[A-Za-z0-9]{20,})', '[TOKEN-REDACTED]'
    $s = $s -replace '(?i)(bearer\s+)[A-Za-z0-9\._\-]{12,}', '$1[TOKEN-REDACTED]'
    $s = $s -replace '(?i)((api[_-]?key|token|secret|password)\s*[:=]\s*)\S+', '$1[REDACTED]'
    $s = $s -replace '[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}', '[EMAIL]'
    return $s
}

$prompts = New-Object System.Collections.Generic.List[object]
$toolCount = @{}
$sessions = @{}
$agentRuns = New-Object System.Collections.Generic.List[object]

foreach ($machineDir in Get-ChildItem (Join-Path $root 'Devlog\raw') -Directory -ErrorAction SilentlyContinue) {
    $dayDir = Join-Path $machineDir.FullName $Date
    if (-not (Test-Path $dayDir)) { continue }
    foreach ($f in Get-ChildItem $dayDir -Filter 'claude-*.jsonl') {
        foreach ($line in [IO.File]::ReadAllLines($f.FullName, $utf8)) {
            try { $o = $line | ConvertFrom-Json } catch { continue }
            $sessions["$($o.machine)/$($o.session)"] = $true
            if ($o.event -eq 'UserPromptSubmit') {
                $prompts.Add([pscustomobject]@{ ts = $o.ts_utc; machine = $o.machine; text = (Redact ([string]$o.payload.prompt)) })
            } elseif ($o.event -eq 'PostToolUse') {
                $k = [string]$o.payload.tool_name
                if ($toolCount.ContainsKey($k)) { $toolCount[$k]++ } else { $toolCount[$k] = 1 }
            }
        }
    }
    $aj = Join-Path $dayDir 'agents.jsonl'
    if (Test-Path $aj) {
        foreach ($line in [IO.File]::ReadAllLines($aj, $utf8)) {
            try { $o = $line | ConvertFrom-Json } catch { continue }
            if ($o.event -eq 'end') { $agentRuns.Add($o) }
            elseif ($o.event -eq 'start') { $agentRuns.Add($o) }
        }
    }
}

$mcpCalls = 0
foreach ($u in Get-ChildItem (Join-Path $root 'Devlog\raw') -Recurse -Filter *.jsonl -ErrorAction SilentlyContinue | Where-Object { $_.Directory.Name -eq 'unreal' }) {
    foreach ($line in [IO.File]::ReadAllLines($u.FullName, $utf8)) {
        if ($line -match ('"log_ts":"' + $Date.Replace('-', '.'))) { if ($line -match 'Dispatching tool') { $mcpCalls++ } }
    }
}

$gitLog = ''
try { $gitLog = (git log --since="$Date 00:00:00 +0000" --until="$Date 23:59:59 +0000" --pretty=format:'- `%h` %s' 2>$null | Out-String) } catch {}

$sb = New-Object System.Text.StringBuilder
[void]$sb.AppendLine("# Day $Date - generated DRAFT (complete it with TEMPLATE_DAY.md)")
[void]$sb.AppendLine()
[void]$sb.AppendLine("## Automatic data")
[void]$sb.AppendLine("- Claude Code sessions: $($sessions.Count)")
[void]$sb.AppendLine("- Team prompts to agents: $($prompts.Count)")
[void]$sb.AppendLine("- External agent runs: $(@($agentRuns | Where-Object event -eq 'start').Count)")
[void]$sb.AppendLine("- MCP calls inside Unreal: $mcpCalls")
[void]$sb.AppendLine()
[void]$sb.AppendLine("### Tools used by Claude Code")
foreach ($k in ($toolCount.Keys | Sort-Object { -$toolCount[$_] })) { [void]$sb.AppendLine("- $k : $($toolCount[$k])") }
[void]$sb.AppendLine()
[void]$sb.AppendLine("### External agents")
foreach ($r in ($agentRuns | Where-Object event -eq 'end')) {
    $s = $agentRuns | Where-Object { $_.event -eq 'start' -and $_.run -eq $r.run } | Select-Object -First 1
    [void]$sb.AppendLine(("- {0} {1} ({2}) exit={3} {4}s - {5}" -f $r.ts_utc, $r.agent, $s.model, $r.exit_code, $r.seconds, (Redact ([string]$s.purpose))))
}
[void]$sb.AppendLine()
[void]$sb.AppendLine("### Commits of the day")
[void]$sb.AppendLine($gitLog)
[void]$sb.AppendLine("### Prompts (redacted, in order; translate any quoted in the day entry)")
foreach ($p in ($prompts | Sort-Object ts)) {
    $t = $p.text; if ($t.Length -gt 600) { $t = $t.Substring(0, 600) + ' ...' }
    [void]$sb.AppendLine(("- **{0}** [{1}] {2}" -f $p.ts, $p.machine, ($t -replace "`r?`n", ' ')))
}

$outDir = Join-Path $root 'Devlog\days'
[void][IO.Directory]::CreateDirectory($outDir)
$out = Join-Path $outDir "$($Date)_DRAFT.md"
[IO.File]::WriteAllText($out, $sb.ToString(), $utf8)
Write-Host "Draft: $out"
