    try { Add-Content -Path (Join-Path ([IO.Path]::GetTempPath()) 'jam-cursor-hook-errors.log') -Value ("{0} {1}" -f [DateTime]::UtcNow.ToString('o'), $_.Exception.Message) } catch {}
}
if ($event -eq 'beforeSubmitPrompt') { '{"continue":true}' } else { '{}' }
exit 0

